fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    assert!(!v.is_empty());
    assert!(end < v.len());

    let mut max_val = v[0];
    let mut max_idx = 0usize;

    for i in 1..=end {
        if v[i] > max_val {
            max_val = v[i];
            max_idx = i;
        }
    }
    (max_val, max_idx)
}

fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    assert!(!v.is_empty());
    assert!(start < v.len());

    let mut min_val = v[start];
    let mut min_idx = start;

    for i in (start + 1)..v.len() {
        if v[i] < min_val {
            min_val = v[i];
            min_idx = i;
        }
    }
    (min_val, min_idx)
}

fn barrier(v: &[i32], p: usize) -> bool {
    assert!(!v.is_empty());
    assert!(p < v.len());

    // If p is the last index, there are no elements to the right: vacuously true.
    if p + 1 >= v.len() {
        return true;
    }

    let (max_left, _) = find_max_in_prefix(v, p);
    let (min_right, _) = find_min_in_suffix(v, p + 1);
    max_left < min_right
}